{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T235858Z/cell-LPreWg/src/nodes.js","content":"/**
 * The value tree the parser builds. Each node carries a `kind` tag:
 * `table`, `arrayOfTables`, `array`, `string`, `integer`, `float` or
 * `boolean`. Tables and arrays of tables are mutable containers built up
 * while parsing; the rest are immutable leaves.
 */

/** A fresh, empty table. `headerDefined` tracks whether a bare `[name]`
 * header has already claimed this exact table, per the specification's rule
 * that such a table may not be named by a second `[name]` header. */
export function makeTable() {
  return { kind: 'table', entries: new Map(), headerDefined: false }
}

/** A fresh, empty array of tables. */
export function makeArrayOfTables() {
  return { kind: 'arrayOfTables', items: [] }
}

export function makeArray(items) {
  return { kind: 'array', items }
}

export function makeScalar(kind, value) {
  return { kind, value }
}

/** The last element of an array of tables, which is what a header walks
 * into when its dotted name passes through one. */
export function lastTable(arrayOfTables) {
  return arrayOfTables.items[arrayOfTables.items.length - 1]
}

/** `keys` mode's type name for a node; an array of tables reads as `array`. */
export function typeName(node) {
  if (node.kind === 'arrayOfTables') return 'array'
  return node.kind
}
"}

