{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T235858Z/cell-LPreWg/src/parser.js","content":"/**
 * The configuration document parser. `parseDocument` turns the raw text
 * into the tree of nodes described in `nodes.js`, or throws a `CliError`
 * naming the first line that fails to parse.
 */
import { CliError } from './errors.js'
import { makeTable, makeArrayOfTables, makeArray, makeScalar, lastTable } from './nodes.js'

const NAME_CHAR = /[A-Za-z0-9_-]/
const DIGIT_RUN = String.raw`\d+(?:_\d+)*`
const INTEGER_RE = new RegExp(`^[+-]?${DIGIT_RUN}$`)
const FLOAT_RE = new RegExp(
  `^[+-]?${DIGIT_RUN}(?:\\.${DIGIT_RUN}(?:[eE][+-]?${DIGIT_RUN})?|[eE][+-]?${DIGIT_RUN})$`,
)

function isSpace(ch) {
  return ch === ' ' || ch === '\t'
}

function isCommentChar(ch) {
  return ch === '#' || ch === ';'
}

/** Parses one line at a time, keeping the document's tables and the
 * currently open table across lines. */
class LineParser {
  constructor(line, lineNo) {
    this.line = line
    this.lineNo = lineNo
    this.pos = 0
  }

  fail(reason) {
    throw new CliError(this.lineNo, reason)
  }

  peek() {
    return this.line[this.pos]
  }

  atEnd() {
    return this.pos >= this.line.length
  }

  skipSpaces() {
    while (!this.atEnd() && isSpace(this.peek())) this.pos++
  }

  /** True when nothing but a comment (or nothing at all) remains. Does not
   * consume anything: the comment, if any, runs to the end of the line. */
  atCommentOrEnd() {
    return this.atEnd() || isCommentChar(this.peek())
  }

  requireTrailingCommentOrEnd(reason) {
    this.skipSpaces()
    if (!this.atCommentOrEnd()) this.fail(reason)
  }

  parseBasicString() {
    this.pos++ // opening quote
    let result = ''
    for (;;) {
      if (this.atEnd()) this.fail('unterminated string')
      const ch = this.line[this.pos]
      if (ch === '"') {
        this.pos++
        return result
      }
      if (ch === '\\') {
        this.pos++
        if (this.atEnd()) this.fail('unterminated string')
        const esc = this.line[this.pos]
        if (esc === '"') result += '"'
        else if (esc === '\\') result += '\\'
        else if (esc === 'n') result += '\n'
        else if (esc === 't') result += '\t'
        else if (esc === 'r') result += '\r'
        else if (esc === '0') result += '\0'
        else if (esc === 'u') {
          const hex = this.line.slice(this.pos + 1, this.pos + 5)
          if (hex.length !== 4 || !/^[0-9a-fA-F]{4}$/.test(hex)) this.fail('invalid escape \\u')
          result += String.fromCharCode(parseInt(hex, 16))
          this.pos += 4
        } else {
          this.fail(`invalid escape \\${esc}`)
        }
        this.pos++
        continue
      }
      result += ch
      this.pos++
    }
  }

  parseLiteralString() {
    this.pos++ // opening quote
    const start = this.pos
    while (!this.atEnd() && this.line[this.pos] !== "'") this.pos++
    if (this.atEnd()) this.fail('unterminated string')
    const result = this.line.slice(start, this.pos)
    this.pos++ // closing quote
    return result
  }

  /** A bare word or quoted string used as one segment of a dotted name. */
  parseName() {
    this.skipSpaces()
    if (this.atEnd()) this.fail('expected a name')
    const ch = this.peek()
    if (ch === '"') return this.parseBasicString()
    if (ch === "'") return this.parseLiteralString()
    const start = this.pos
    while (!this.atEnd() && NAME_CHAR.test(this.peek())) this.pos++
    if (this.pos === start) this.fail('expected a name')
    return this.line.slice(start, this.pos)
  }

  /** Names joined by `.`, with spaces and tabs allowed around each dot. */
  parseDottedName() {
    const names = [this.parseName()]
    for (;;) {
      this.skipSpaces()
      if (this.atEnd() || this.peek() !== '.') break
      this.pos++
      names.push(this.parseName())
    }
    return names
  }

  /** A value's bareword form: `true`, `false`, an integer or a float. Grabs
   * every character up to the next whitespace, comma or closing bracket, so
   * a value that runs into a `#` swallows it as part of its own text. */
  parseBareword() {
    const start = this.pos
    while (
      !this.atEnd() &&
      !isSpace(this.peek()) &&
      this.peek() !== ',' &&
      this.peek() !== ']' &&
      this.peek() !== '}'
    ) {
      this.pos++
    }
    const token = this.line.slice(start, this.pos)
    if (token === 'true') return makeScalar('boolean', true)
    if (token === 'false') return makeScalar('boolean', false)
    if (INTEGER_RE.test(token)) return makeScalar('integer', Number(token.replace(/_/g, '')))
    if (FLOAT_RE.test(token)) return makeScalar('float', Number(token.replace(/_/g, '')))
    this.fail(`invalid value ${token}`)
  }

  /** Parses a value. `path` is the absolute dotted path this value is
   * destined for, used to build error messages for keys nested inside an
   * inline table this value might turn out to be. */
  parseValue(path) {
    this.skipSpaces()
    if (this.atEnd() || isCommentChar(this.peek())) this.fail('expected a value')
    const ch = this.peek()
    if (ch === '"') return makeScalar('string', this.parseBasicString())
    if (ch === "'") return makeScalar('string', this.parseLiteralString())
    if (ch === '[') return this.parseArrayValue(path)
    if (ch === '{') return this.parseInlineTableValue(path)
    if (ch === ',' || ch === ']' || ch === '}') this.fail('expected a value')
    return this.parseBareword()
  }

  parseArrayValue(path) {
    this.pos++ // '['
    const items = []
    for (;;) {
      this.skipSpaces()
      if (this.atEnd() || isCommentChar(this.peek())) this.fail('unterminated array')
      if (this.peek() === ']') {
        this.pos++
        break
      }
      items.push(this.parseValue(path))
      this.skipSpaces()
      if (this.atEnd() || isCommentChar(this.peek())) this.fail('unterminated array')
      if (this.peek() === ',') {
        this.pos++
        continue
      }
      if (this.peek() === ']') {
        this.pos++
        break
      }
      this.fail('trailing text after a value')
    }
    return makeArray(items)
  }

  parseInlineTableValue(path) {
    this.pos++ // '{'
    const table = makeTable()
    this.skipSpaces()
    if (this.atEnd() || isCommentChar(this.peek())) this.fail('unterminated inline table')
    if (this.peek() === '}') {
      this.pos++
      return table
    }
    for (;;) {
      const names = this.parseDottedName()
      this.skipSpaces()
      if (this.atEnd() || isCommentChar(this.peek())) this.fail('unterminated inline table')
      if (this.peek() !== '=') this.fail('expected = in an inline table')
      this.pos++
      const value = this.parseValue(path)
      setKeyPath(this, table, path, names, value)
      this.skipSpaces()
      if (this.atEnd() || isCommentChar(this.peek())) this.fail('unterminated inline table')
      if (this.peek() === ',') {
        this.pos++
        continue
      }
      if (this.peek() === '}') {
        this.pos++
        break
      }
      this.fail('trailing text after a value')
    }
    return table
  }
}

/** Assigns `value` at `names` (relative to `table`, whose absolute path is
 * `basePath`), creating the tables the dots walk through. */
function setKeyPath(lp, table, basePath, names, value) {
  let node = table
  const path = basePath.slice()
  for (let i = 0; i < names.length; i++) {
    const name = names[i]
    path.push(name)
    const isLast = i === names.length - 1
    if (isLast) {
      if (node.entries.has(name)) lp.fail(`key ${path.join('.')} is defined twice`)
      node.entries.set(name, value)
      return
    }
    let existing = node.entries.get(name)
    if (existing === undefined) {
      existing = makeTable()
      node.entries.set(name, existing)
    }
    if (existing.kind === 'arrayOfTables') {
      node = lastTable(existing)
      continue
    }
    if (existing.kind !== 'table') lp.fail(`${path.join('.')} is not a table`)
    node = existing
  }
}

/** Walks from `root` to the table a `[name]` header names, creating tables
 * along the way and marking the final one as header-defined. */
function walkHeaderTable(lp, root, names) {
  let node = root
  const path = []
  for (let i = 0; i < names.length; i++) {
    const name = names[i]
    path.push(name)
    const isLast = i === names.length - 1
    let existing = node.entries.get(name)
    if (existing === undefined) {
      existing = makeTable()
      node.entries.set(name, existing)
    }
    if (existing.kind === 'arrayOfTables') {
      if (!isLast) {
        node = lastTable(existing)
        continue
      }
      lp.fail(`${path.join('.')} is not a table`)
    }
    if (existing.kind !== 'table') lp.fail(`${path.join('.')} is not a table`)
    if (isLast) {
      if (existing.headerDefined) lp.fail(`table ${path.join('.')} is defined twice`)
      existing.headerDefined = true
      return existing
    }
    node = existing
  }
}

/** Walks from `root` to the array of tables a `[[name]]` header names,
 * appending a fresh table to it and returning that table. */
function walkArrayHeaderTable(lp, root, names) {
  let node = root
  const path = []
  for (let i = 0; i < names.length - 1; i++) {
    const name = names[i]
    path.push(name)
    let existing = node.entries.get(name)
    if (existing === undefined) {
      existing = makeTable()
      node.entries.set(name, existing)
    }
    if (existing.kind === 'arrayOfTables') {
      node = lastTable(existing)
      continue
    }
    if (existing.kind !== 'table') lp.fail(`${path.join('.')} is not a table`)
    node = existing
  }
  const lastName = names[names.length - 1]
  path.push(lastName)
  let arrayOfTables = node.entries.get(lastName)
  if (arrayOfTables === undefined) {
    arrayOfTables = makeArrayOfTables()
    node.entries.set(lastName, arrayOfTables)
  } else if (arrayOfTables.kind !== 'arrayOfTables') {
    lp.fail(`${path.join('.')} is not an array of tables`)
  }
  const table = makeTable()
  arrayOfTables.items.push(table)
  return table
}

function parseHeaderLine(lp, root) {
  lp.skipSpaces()
  lp.pos++ // '['
  let isArrayHeader = false
  if (!lp.atEnd() && lp.peek() === '[') {
    isArrayHeader = true
    lp.pos++
  }
  const names = lp.parseDottedName()
  lp.skipSpaces()
  if (lp.atEnd() || lp.peek() !== ']') lp.fail('unterminated table header')
  lp.pos++
  if (isArrayHeader) {
    lp.skipSpaces()
    if (lp.atEnd() || lp.peek() !== ']') lp.fail('unterminated table header')
    lp.pos++
  }
  lp.requireTrailingCommentOrEnd('trailing text after a table header')
  return isArrayHeader
    ? walkArrayHeaderTable(lp, root, names)
    : walkHeaderTable(lp, root, names)
}

function parseAssignmentLine(lp, currentTable, currentPath) {
  const names = lp.parseDottedName()
  lp.skipSpaces()
  if (lp.atEnd() || lp.peek() !== '=') lp.fail('expected key = value')
  lp.pos++
  const value = lp.parseValue(currentPath.concat(names))
  lp.requireTrailingCommentOrEnd('trailing text after a value')
  setKeyPath(lp, currentTable, currentPath, names, value)
}

/** Splits the document into lines, dropping the empty tail a trailing
 * newline leaves. */
function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

export function parseDocument(text) {
  const root = makeTable()
  let currentTable = root
  let currentPath = []
  const lines = splitLines(text)
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    const lineNo = i + 1
    let start = 0
    while (start < line.length && isSpace(line[start])) start++
    if (start === line.length || isCommentChar(line[start])) continue

    const lp = new LineParser(line, lineNo)
